function compileItemHooks(def) {
  const hooks = {};
  for (const [dslName, catalogName] of Object.entries(ITEM_HOOK_MAP)) {
    if (typeof def[dslName] === 'function') {
      hooks[catalogName] = compileHook(def[dslName]);
    }
